llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C71"],
      "claim": "Telmisartan absolute oral bioavailability was 57.4% for a 160 mg tablet relative to IV infusion in healthy male volunteers, well above the 20% threshold."
    },
    {
      "card_ids": ["C38"],
      "claim": "Safinamide absolute oral bioavailability was 95.0% (83.9–119.3%) after a 50 mg IR tablet in fasted subjects, strongly supporting high bioavailability."
    },
    {
      "card_ids": ["C59"],
      "claim": "Pazopanib absolute oral bioavailability was estimated at 21.4% (range 13.5–38.9%) in cancer patients, a mean value above the 20% threshold but with some uncertainty."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All ten evidence molecules have condition-matched absolute oral bioavailability values at or above 20%; the lowest point estimates are pazopanib 21.4% and celecoxib 20–40%, both meeting the threshold. Thus the query is predicted high.",
  "evidence_gaps": [
    "Pazopanib's mean F is close to the threshold and its range extends below 20%, adding uncertainty.",
    "Rigosertib fed-state F of 13.9% is below threshold but was discounted as an altered condition.",
    "Celecoxib's reported range starts at 20%, so threshold classification is borderline."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C71", "C38", "C59"],
  "revision_action": "initial",
  "supportive_card_ids": ["C71", "C38", "C59"]
}

